/* The game's debug print, compiled to nothing but its arguments: the strings stay in .rodata,
 * in source order (IDO_NOTES 144, 201). The arguments are not known: no code is left.
 * The segment number is printed with "%04d" or "%04x": two adjacent strings with nothing
 * between them, so one or the other, chosen by a test that leaves no code but a live range
 * (fileServiceQueue, fileLoadOverlay), written "file < 0x8000" (decimal for a file, hex for
 * a sub-file, the bound fileRomSize uses). The other functions have them as two plain lines. */
#define DPRINTF

/* The file loader: a queue of load requests (include/file.h), serviced by fileServiceQueue once a
 * frame; "now" variants run a request at once, with the queue set aside. */

extern s32 gSysArenaBottom;
extern s32 gSysArenaTop;
extern s32 gSysArenaBase;
extern u8 gFileLoaderBusy; /* the loading flag */

extern u32 gFileTlbPhys;
extern u32 gFileRomOffsets[];      /* file offsets: file N's ROM start is [N-1] (bit 31: compressed) */
/* file N's RAM range: [(N-1)*2] start (bit 30: TLB-mapped), [(N-1)*2+1] end. A flat u32 array:
 * indexed as a struct array, IDO folds the -8 into the loads, and the original does not. */
extern u32 gFileRamRangeTable[];
extern u16 gFileGroupTable[];      /* (first file, group) pairs, 0-terminated */
#define FILE_COUNT 2576
extern u32 gFileTlbFile;
extern u32 gFileTlbPagePhys[32]; /* the physical address mapped at each TLB page, 8 KB each */
extern u16 gPtxParentTable[];   /* sub-files: (first sub-file, parent file) pairs, 0-terminated */
extern u32 gPtxOffsetTable[];   /* sub-file N's offset in its parent is [N - 0x8000] (24 bits) */
extern u32 *gFileAttachTable[]; /* per file: (address, target) pairs, 0-terminated */
extern u16 gFramebuffers[3][SCREEN_WIDTH * SCREEN_HEIGHT]; /* the framebuffers */
typedef struct FileTableHeader {
    /* 0x00 */ u8 magic[16]; /* "Nisitenma-Ichigo" */
    /* 0x10 */ u32 offsets[FILE_COUNT + 2]; /* the ROM start of file N is [N-1] (bit 31: compressed) */
} FileTableHeader;
extern FileTableHeader gFileRomTable;

void fileInit(void) {
    fileClearQueue();
    romClearBuf();
}

/* Empty the request queue. */
void fileClearQueue(void) {
    s32 i;

    gSysArenaBottom = gSysArenaTop = gSysArenaBase = 0;
    gFileQueueCount = 0;
    for (i = 0; i < 8; i++) {
        gFileQueue[i].list = NULL;
    }
}

void fileQueueList(FileList *list) {
    fileQueueListMode(list, 0);
}

void fileQueueListKeep(FileList *list) {
    fileQueueListMode(list, 1);
}

/* Queue a list of files. */
void fileQueueListMode(FileList *list, u8 mode) {
    u8 n = gFileQueueCount;
    FileReq *req = &gFileQueue[n];

    req->list = list;
    gFileQueueCount = n + 1;
    req->mode = mode;
}

void fileQueue(u32 file, void *ram) {
    fileQueueMode(file, ram, 0);
}

void fileQueueKeep(u32 file, void *ram) {
    fileQueueMode(file, ram, 1);
}

/* Queue one file, through an entry of the single-file pool. */
void fileQueueMode(u32 file, void *ram, u8 mode) {
    u16 m = gFileSingleListUsed;
    FileList *entry = &gFileQueueSingleList[m];
    u8 n = gFileQueueCount;
    FileReq *req = &gFileQueue[n];

    entry->file = file | FILELIST_LAST;
    entry->ram = ram;
    req->mode = mode;
    gFileQueueCount = n + 1;
    gFileSingleListUsed = m + 1;
    req->list = entry;
}

void fileLoadListNow(FileList *list) {
    fileLoadListNowMode(list, 0);
}

void fileLoadListNowKeep(FileList *list) {
    fileLoadListNowMode(list, 1);
}

/* Load a list of files now: set the queue aside, run the loader with the loading flag up, and
 * put the queue back. (The call and the flag's clear share a line: IDO schedules by line.) */
void fileLoadListNowMode(FileList *list, u8 mode) {
    s32 i;
    FileReq saved[8];
    u8 count;

    count = gFileQueueCount;
    gFileQueueCount = 0;
    for (i = 0; i < 8; i++) {
        saved[i].list = gFileQueue[i].list;
        saved[i].mode = gFileQueue[i].mode;
        gFileQueue[i].list = NULL;
        gFileQueue[i].mode = 0;
    }
    gFileQueue[0].mode = mode;
    gFileQueue[0].list = list;
    gFileLoaderBusy = 1;
    fileServiceQueue(); gFileLoaderBusy = 0;
    gFileQueueCount = count;
    for (i = 0; i < 8; i++) {
        gFileQueue[i].list = saved[i].list;
        gFileQueue[i].mode = saved[i].mode;
    }
}

/* Load one file now (thread 5 registers each file's RAM this way at boot). */
void fileLoadNow(u32 file, void *ram) {
    fileLoadNowMode(file, ram, 0);
}

void fileLoadNowKeep(u32 file, void *ram) {
    fileLoadNowMode(file, ram, 1);
}

void fileLoadNowMode(u32 file, void *ram, u8 mode) {
    FileList entry;

    entry.file = file | FILELIST_LAST;
    entry.ram = ram;
    if (mode == 0) {
        fileLoadListNow(&entry);
    }
    if (mode == 1) {
        fileLoadListNowKeep(&entry);
    }
}

/* The loader, once a frame (and at once for "now" requests): for each queued list, load every
 * file that is not already resident, by its entry's RAM field (0: allocate; -1: the next free
 * address; else that address), then hand it to fileLoadAttachments. Stops when resGetFile says so.
 * The inner loop is an unrotated for (;;) with the call test first and "if (last) break;
 * entry++;" written in both paths (the original's two tails); the RAM field is an UNSIGNED
 * switch, case -1, case 0, default in that order (tests 0 then -1; a signed switch tests -1
 * first). The lookup compare is u32, so it shares the switch's -1 (s4). The original saves s7
 * and never writes it: the constant 0x8000 of the segment number's print (decimal for a file,
 * hex for a sub-file; see DPRINTF above), which uopt hoists out of the loop and colours s7
 * (uopt -zdbug:5: range 64, const 32768, priority 11.1, one use in the print's block) before
 * ugen drops the empty test with it. That range pushes req to fp and spills i at 0x47. (Until
 * 2026-10-04 a FAKE empty test, "(s32) file == -1" above the lookup, made it.) Entries
 * indexed entry[j] keep j (no strength reduction). */
void fileServiceQueue(void) {
    u8 i;
    FileReq *req = gFileQueue;
    FileList *entry;
    u32 file;
    u16 id;
    u8 mode;
    void *addr;

    for (i = 0; i < 8; i++, req++) {
        if (req->list != NULL) {
            entry = req->list;
            mode = req->mode;
            for (;;) {
                if (resGetFile(resCount()) != 0) {
                    DPRINTF("segw が一杯で展開できません。\n");
                    break;
                }
                file = entry->file & 0x0FFFFFFF;
                id = file;
                if ((u32) resFindFile(id) != 0xFFFFFFFF) {
                    DPRINTF("すでにセグメント[");
                    if (file < 0x8000) {
                        DPRINTF("%04d", file);
                    } else {
                        DPRINTF("%04x", file);
                    }
                    DPRINTF("] は展開されています。\n");
                    if (entry->file & FILELIST_LAST) {
                        break;
                    }
                    entry++;
                    continue;
                }
                switch ((u32) entry->ram) {
                    case 0xFFFFFFFF:
                        addr = (void *) fileLoadAtNextFree(file, mode);
                        break;
                    case 0:
                        addr = fileAllocAndLoad(file, mode);
                        break;
                    default:
                        addr = fileLoadToAddr(file, entry->ram, mode);
                        break;
                }
                fileLoadAttachments(id, addr);
                if (entry->file & FILELIST_LAST) {
                    break;
                }
                entry++;
            }
            req->list = NULL;
        }
    }
    gFileQueueCount = 0;
    gFileSingleListUsed = 0;
}

/* Load a file at the next free address (4 KB-aligned if it is TLB-mapped, else 8-aligned). */
u32 fileLoadAtNextFree(u32 file, u8 mode) {
    u32 addr = resGetAddr(resCount());

    if (addr == 0) {
        DPRINTF("Error:dest is NULL\n");
        return 0;
    }
    if (fileIsTlbMapped(file)) {
        addr = (addr + 0xFFF) & ~0xFFF;
    } else {
        addr = (addr + 7) & ~7;
    }
    resRegister(file, addr, (u32) fileLoad(file, (void *) addr) - addr, mode);
    return addr;
}

/* An empty function nothing calls (jr ra; nop at 0x80003D24). splat folds it into the function
 * above, since no symbol marks it, and ignores a symbol_addrs entry placed inside a function it
 * has already found. */
void fileEmptyStub(void) {
}

/* Allocate room for a file (from the TLB pool if it is TLB-mapped) and load it there. */
void *fileAllocAndLoad(u32 file, u8 mode) {
    void *ram;
    s32 size;

    if (file == 0 || file > FILE_COUNT) {
        DPRINTF("セグメント[");
        DPRINTF("%04d");
        DPRINTF("%04x");
        DPRINTF("] が _ENDSIZESegmentRomNo をオーバーしています(展開エラー)\n");
        return NULL;
    }
    size = gFileRamRangeTable[(file - 1) * 2 + 1] - gFileRamRangeTable[(file - 1) * 2];
    if (fileIsTlbMapped(file)) {
        ram = heapMallocPage(size);
        if (ram != NULL) {
            fileLoad(file, ram);
            resPush(file, (void *) ((u32) ram | 0x40000000), mode);
            return ram;
        }
    } else {
        ram = heapMalloc(size);
        if (ram != NULL) {
            fileLoad(file, ram);
            resPush(file, ram, mode);
        }
    }
    return ram;
}

/* Load a file to a given address. */
void *fileLoadToAddr(u32 file, void *ram, u8 mode) {
    if (ram == NULL) {
        DPRINTF("Error:adr is NULL\n");
        return NULL;
    }
    resPush(file, ram, mode);
    fileLoad(file, ram);
    return ram;
}

/* LoadFile: file N to ram. A compressed file (its offset's bit 31) is decoded (romDecode) and
 * the caches are flushed over it; a plain one is DMA'd, rounded up to an even size. The rest of
 * its RAM range is zeroed (its BSS). Returns the end of the range.
 * The index is `file - 1` written inline each time (a k local stays live into the branch; inline,
 * the branch rebuilds it from file). The decoded and DMA'd lengths are inline expressions, not a
 * local (their compiler temp is the 0x20 slot). "i = 16" sits above the zeroing loop, which keeps
 * the delay loop's first test (li 16; beqz). The decoder's length is a SIGNED subtraction: its
 * (s32) rom is a different load from the u32 rom argument, so rom is read twice, as the original. */
void *fileLoad(u32 file, u8 *ram) {
    u32 rom;
    u32 size;
    u8 saved;
    u8 *end;
    u8 *p;
    u8 i;

    p = ram;
    if (file == 0 || file > FILE_COUNT) {
        DPRINTF("セグメント[");
        DPRINTF("%04d");
        DPRINTF("%04x");
        DPRINTF("] が _ENDSIZESegmentRomNo をオーバーしています(展開エラー)\n");
        return NULL;
    }
    rom = gFileRomTable.offsets[file - 1] & 0x7FFFFFFF;
    size = (gFileRomTable.offsets[file - 1 + 1] & 0x7FFFFFFF) - rom;
    end = ram + (gFileRamRangeTable[(file - 1) * 2 + 1] - gFileRamRangeTable[(file - 1) * 2]);
    saved = gFileLoaderBusy;
    gFileLoaderBusy = 1;
    if (size != 0) {
        if (gFileRomTable.offsets[file - 1] & 0x80000000) {
            p = romDecode(rom, ram,
                                   (s32) (gFileRomTable.offsets[file - 1 + 1] & 0x7FFFFFFF) - (s32) rom);
            osWritebackDCache(ram, p - ram);
            osInvalDCache(ram, p - ram);
            osInvalICache(ram, p - ram);
        } else {
            dmaReadRom(gFileRomTable.offsets[file - 1], ram, (size + 1) & ~1);
            p += (size + 1) & ~1;
        }
    }
    gFileLoaderBusy = saved;
    i = 16;
    while (p < end) {
        *p++ = 0;
    }
    while (i--) {
    }
    return end;
}

/* After a load: walk the file's table of (address, target) pairs (0x8003514C, by file) and hand
 * each to fileLoadAttachment, the target moved by where the file landed relative to its group's base
 * (group << 24). Returns 1, or 0 with no RAM or no group. */
s32 fileLoadAttachments(u16 file, void *ram) {
    s32 i = 0;
    u32 *pairs;
    u32 delta;
    u32 x;

    if (ram == NULL) {
        DPRINTF("Error:destination is NULL\n");
        return 0;
    }
    pairs = gFileAttachTable[file];
    while (file >= gFileGroupTable[i]) {
        i += 2;
        if (gFileGroupTable[i] == 0) {
            DPRINTF("[%x] romNo setting over error!!\n");
            return 0;
        }
    }
    delta = (u32) ram - (gFileGroupTable[i + 1] << 24);
    x = pairs[0];
    while (x != 0) {
        fileLoadAttachment(x, (u8 *) (pairs[1] + delta));
        pairs += 2;
        x = pairs[0];
    }
    return 1;
}

